using FindUpTo.Pos.Server.Models;
using Microsoft.EntityFrameworkCore;
namespace FindUpTo.Pos.Server.Data;
public class PosDbContext(DbContextOptions options) : DbContext(options)
{
    public DbSet<AppUser> Users => Set<AppUser>(); public DbSet<BusinessSetting> BusinessSettings => Set<BusinessSetting>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<Product> Products => Set<Product>(); public DbSet<Customer> Customers => Set<Customer>(); public DbSet<PosTable> Tables => Set<PosTable>(); public DbSet<PosOrder> Orders => Set<PosOrder>(); public DbSet<OrderItem> OrderItems => Set<OrderItem>(); public DbSet<Payment> Payments => Set<Payment>(); public DbSet<Promotion> Promotions => Set<Promotion>(); public DbSet<Conversation> Conversations => Set<Conversation>(); public DbSet<Message> Messages => Set<Message>(); public DbSet<AuditLog> AuditLogs => Set<AuditLog>(); public DbSet<CashDrawerSession> CashDrawerSessions => Set<CashDrawerSession>(); public DbSet<CashDrawerMovement> CashDrawerMovements => Set<CashDrawerMovement>(); public DbSet<SyncOperation> SyncOperations => Set<SyncOperation>(); public DbSet<SyncConflict> SyncConflicts => Set<SyncConflict>(); public DbSet<RelayDevice> RelayDevices => Set<RelayDevice>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<AppUser>().HasIndex(x => x.Username).IsUnique(); modelBuilder.Entity<AppUser>().Property(x => x.Username).HasMaxLength(64); modelBuilder.Entity<AppUser>().Property(x => x.Role).HasMaxLength(32); modelBuilder.Entity<BusinessSetting>().Property(x => x.BusinessName).HasMaxLength(160); modelBuilder.Entity<BusinessSetting>().Property(x => x.CurrencyCode).HasMaxLength(8); modelBuilder.Entity<BusinessSetting>().Property(x => x.CurrencySymbol).HasMaxLength(16); modelBuilder.Entity<Category>().Property(x => x.Name).HasMaxLength(120); modelBuilder.Entity<Product>().Property(x => x.Name).HasMaxLength(160); modelBuilder.Entity<Product>().Property(x => x.Barcode).HasMaxLength(64); modelBuilder.Entity<Product>().HasIndex(x => x.Barcode).IsUnique(); modelBuilder.Entity<Customer>().Property(x => x.Phone).HasMaxLength(32); modelBuilder.Entity<PosTable>().Property(x => x.Name).HasMaxLength(64); modelBuilder.Entity<PosTable>().Property(x => x.Status).HasMaxLength(32); modelBuilder.Entity<PosOrder>().Property(x => x.OrderType).HasMaxLength(32); modelBuilder.Entity<PosOrder>().Property(x => x.Status).HasMaxLength(32); modelBuilder.Entity<OrderItem>().Property(x => x.ProductName).HasMaxLength(160); modelBuilder.Entity<OrderItem>().HasOne<PosOrder>().WithMany(x => x.Items).HasForeignKey(x => x.PosOrderId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<Payment>().Property(x => x.Method).HasMaxLength(32); modelBuilder.Entity<Payment>().Property(x => x.Status).HasMaxLength(32); modelBuilder.Entity<Promotion>().Property(x => x.Name).HasMaxLength(160); modelBuilder.Entity<Promotion>().Property(x => x.DiscountType).HasMaxLength(16); modelBuilder.Entity<Conversation>().Property(x => x.Participants).HasMaxLength(2000); modelBuilder.Entity<Message>().Property(x => x.SenderUsername).HasMaxLength(64); modelBuilder.Entity<Message>().Property(x => x.Text).HasMaxLength(4000); modelBuilder.Entity<AuditLog>().Property(x => x.Username).HasMaxLength(64); modelBuilder.Entity<AuditLog>().Property(x => x.Action).HasMaxLength(64); modelBuilder.Entity<AuditLog>().Property(x => x.EntityType).HasMaxLength(64); modelBuilder.Entity<AuditLog>().Property(x => x.EntityId).HasMaxLength(64); modelBuilder.Entity<AuditLog>().Property(x => x.Details).HasMaxLength(4000); modelBuilder.Entity<CashDrawerSession>().Property(x => x.OpenedByUsername).HasMaxLength(64); modelBuilder.Entity<CashDrawerSession>().Property(x => x.Status).HasMaxLength(16); modelBuilder.Entity<CashDrawerSession>().Property(x => x.ClosedByUsername).HasMaxLength(64); modelBuilder.Entity<CashDrawerSession>().Property(x => x.Notes).HasMaxLength(1000); modelBuilder.Entity<CashDrawerMovement>().Property(x => x.Type).HasMaxLength(32); modelBuilder.Entity<CashDrawerMovement>().Property(x => x.Reason).HasMaxLength(500); modelBuilder.Entity<CashDrawerMovement>().Property(x => x.Username).HasMaxLength(64); modelBuilder.Entity<CashDrawerSession>().HasMany(x => x.Movements).WithOne().HasForeignKey(x => x.CashDrawerSessionId).OnDelete(DeleteBehavior.Cascade); modelBuilder.Entity<SyncOperation>().Property(x => x.ClientOperationId).HasMaxLength(128); modelBuilder.Entity<SyncOperation>().Property(x => x.CreatedByUsername).HasMaxLength(64); modelBuilder.Entity<SyncOperation>().HasIndex(x => x.ClientOperationId).IsUnique(); modelBuilder.Entity<SyncConflict>().Property(x => x.ClientOperationId).HasMaxLength(128); modelBuilder.Entity<SyncConflict>().Property(x => x.EntityType).HasMaxLength(64); modelBuilder.Entity<SyncConflict>().Property(x => x.EntityId).HasMaxLength(64); modelBuilder.Entity<SyncConflict>().Property(x => x.Reason).HasMaxLength(256); modelBuilder.Entity<SyncConflict>().Property(x => x.Details).HasMaxLength(4000); modelBuilder.Entity<SyncConflict>().Property(x => x.Username).HasMaxLength(64); modelBuilder.Entity<RelayDevice>().Property(x => x.Name).HasMaxLength(120); modelBuilder.Entity<RelayDevice>().Property(x => x.SecretHash).HasMaxLength(128); modelBuilder.Entity<RelayDevice>().HasIndex(x => x.Name).IsUnique();
    }
}
public sealed class CoreDbContext(DbContextOptions<CoreDbContext> options) : PosDbContext(options);